<article class="branch-card"><div class="branch-number"><?= e(str_pad((string)($index+1),2,'0',STR_PAD_LEFT)) ?><?= icon('pin') ?></div><h3><?= e($branch['name']) ?></h3><?php if($isDemo??true):?><p>Dirección, teléfono y horarios<br>pendientes de confirmar.</p><span class="branch-status">Información por confirmar</span><?php else:?><p><?= e($branch['address']?:'Dirección pendiente de publicación.') ?><?php if($branch['phone']):?><br><?= e($branch['phone']) ?><?php endif?></p><?php if($branch['map_url']):?><a class="branch-status" href="<?= e($branch['map_url']) ?>" target="_blank" rel="noopener">Consultar ubicación</a><?php else:?><span class="branch-status">Ubicación pendiente</span><?php endif?><?php endif?></article>
